from typing import List

class Solution:
    def smallestAbsentPositive(self, nums: List[int]) -> int:
        avg = sum(nums) / len(nums)
        seen = set(nums)
        # Find smallest positive integer strictly greater than average not in nums
        cand = max(1, int(avg) + 1)
        if cand <= avg:
            cand += 1

        while cand in seen:
            cand += 1

        return cand

#include <vector>
#include <unordered_set>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int smallestAbsentPositive(std::vector<int>& nums) {
        double avg = (double)std::accumulate(nums.begin(), nums.end(), 0LL) / nums.size();
        std::unordered_set<int> seen(nums.begin(), nums.end());

        int cand = std::max(1, (int)avg + 1);
        if (cand <= avg) cand++;

        while (seen.count(cand)) {
            cand++;
        }
        return cand;
    }
};

import java.util.*;

class Solution {
    public int smallestAbsentPositive(int[] nums) {
        long sum = 0;
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) {
            sum += x;
            seen.add(x);
        }
        double avg = (double) sum / nums.length;

        int cand = Math.max(1, (int) avg + 1);
        if (cand <= avg) cand++;

        while (seen.contains(cand)) {
            cand++;
        }
        return cand;
    }
}

var smallestAbsentPositive = function(nums) {
    const sum = nums.reduce((acc, x) => acc + x, 0);
    const avg = sum / nums.length;
    const seen = new Set(nums);

    let cand = Math.max(1, Math.floor(avg) + 1);
    if (cand <= avg) cand++;

    while (seen.has(cand)) {
        cand++;
    }
    return cand;
};
